function metric(mysqli $c,string $sql){return $c->query($sql)->fetch_assoc()['total'];}
$today=metric($conn,"SELECT COALESCE(SUM(amount),0) total FROM payments WHERE status='Paid' AND DATE(paid_at)=CURDATE()");
$month=metric($conn,"SELECT COALESCE(SUM(amount),0) total FROM payments WHERE status='Paid' AND YEAR(paid_at)=YEAR(CURDATE()) AND MONTH(paid_at)=MONTH(CURDATE())");
$total=metric($conn,"SELECT COALESCE(SUM(amount),0) total FROM payments WHERE status='Paid'");
$customers=metric($conn,"SELECT COUNT(*) total FROM users WHERE role='user'");
$admins=metric($conn,"SELECT COUNT(*) total FROM users WHERE role='admin' AND account_status='active'");
$services=metric($conn,"SELECT COUNT(*) total FROM services WHERE status='active'");
$unavailable=metric($conn,"SELECT COUNT(*) total FROM services WHERE status='active' AND booking_availability='unavailable'");
